%[text] %[text:anchor:T_0C9A4FA5] # Master Stiffness Matrix and Body Load Vector for the Reissner-Mindlin Plate using Page-Wise Computations and `sparse`-Matrices
%[text] Computation of the master stiffness matrix and master load vector corresponding to the standard Reissner-Mindlin plate formulation with three degrees of freedom per node $\\left(w,\\beta\_x ,\\beta\_y \\right)${"editStyle":"visual"}, the vertical deflection and two rotations of the plate's cross section around the $X${"editStyle":"visual"}- and the $Y${"editStyle":"visual"}-axis, respectively, using [page-wise](https://blogs.mathworks.com/loren/2021/01/14/paged-matrix-functions/) computation of the element stiffness matrices [`sparse`](https://www.mathworks.com/help/matlab/ref/sparse.html)-matrices for the assembly. A schematic of this workflow is shown in the following figure:
%[text]{"align":"center"} ![pageWiseSetup.png](text:image:760f)
%[text] The master stiffness matrix and master load vector for the standard Reissner-Mindlin plate are given by the following relations:
%[text] $\\begin{array}{ll}\n\\mathbf{K} = \\int\_{A} \\mathbf{B}\_{\\text{s}}^{\\text{T}} \\mathbf{C}\_{\\text{s}} \\mathbf{B}\_{\\text{s}} \\, \\text{d} A+ \\int\_{A} \\mathbf{B}\_{\\text{b}}^{\\text{T}} \\mathbf{C}\_{\\text{b}} \\mathbf{B}\_{\\text{b}} \\: \\text{d} A , & \\text{(1.1)} \\\\\n\\mathbf{F} = \\int\_{A} \\mathbf{N}^{\\text{T}} \\left\[ \\begin{array}{c} \\bar{p} \\\\ \\bar{m}\_x \\\\ \\bar{m}\_y \\end{array} \\right\] \\: \\text{d} A + \\int\_{\\subset\\partial A} \\mathbf{N}^{\\text{T}} \\left\[ \\begin{array}{c} \\bar{P} \\\\ \\bar{M}\_x \\\\ \\bar{M}\_y \\end{array} \\right\] \\: \\text{d} \\partial A . & \\text{(1.2)}\n\\end{array}$
%[text:tableOfContents]{"heading":"**Table of Contents**"}
function [K, F] =  ...
    computeMasterStiffMatrixandForceVctReissnerMindlinPlatePageWise ...
    (msh, computeBasisFunctionsAndDerivs, ~, propStr)
%[text] %[text:anchor:H_A780CBCB] ## Function Description
%[text] Computation of the master stiffness matrix and the master load vector for a plate using the two-dimensional Reissner-Mindlin plate theory with three degrees of freedom per node $\\left(w,\\beta\_x ,\\beta\_y \\right)${"editStyle":"visual"}, the vertical deflection and two rotations of the plate's cross section around the $X${"editStyle":"visual"}- and the $Y${"editStyle":"visual"}-axis, respectively, using a page-wise computation for the element stiffness matrices and subsequently `sparse`-matrices for the assembly.
%[text] %[text:anchor:H_CF0AAACB]  **Input :**
%[text]  `X` : Array containing the nodal coordinates of the nodes in the element
%[text]  `computeBasisFunctionsAndDerivs` : Function handle to the computation of the basis functions
%[text]  `propStr` : Structure containing the following fields,
%[text]  `.t` : Thickness
%[text]  `.pBar` : Distributed load
%[text]  `.mxBar` : Distributed moment around x-axis
%[text]  `.myBar` : Distributed moment around y-axis
%[text]  `.E` : Young's modulus
%[text]  `.nu` : Poisson's ratio
%[text]  `.G` : Shear modulus
%[text]  `.D` : Plate's stiffness
%[text]  `.alpha` : Shear correction factor
%[text] 
%[text] %[text:anchor:H_36331BE7]  **Output :**
%[text]  `K` : Master stiffness matrix of a Reissner-Mindlin plate (`sparse`)
%[text]  `F` : Master force vector of a Reissner-Mindlin plate (`sparse`)
%[text] %[text:anchor:H_BCB97BE8] ## Function Implementation
%[text] %[text:anchor:H_98854650] ### Input validation
    arguments
        msh (1,1) struct {mustHaveNodesAndElements}
        computeBasisFunctionsAndDerivs (1,1) function_handle
        ~
        propStr (1,1) struct {mustHaveReissnerMindlinPlateProperties}
    end
%[text] %[text:anchor:H_E0B89738] ### Check input
    if ~strcmp(func2str(computeBasisFunctionsAndDerivs), ...
            "computeBilinearBasisFunctionsAndFirstDerivatives") && ...
            ~strcmp(func2str(computeBasisFunctionsAndDerivs), ...
            "computeBiquadraticBasisFunctionsAndFirstDerivatives")
        error("Input 'computeBasisFunctionsAndDerivs' is defined as %s but only " + ...
            "values 'computeBilinearBasisFunctionsAndFirstDerivatives' and " + ...
            "'computeBiquadraticBasisFunctionsAndFirstDerivatives' are supported", ...
            computeBasisFunctionsAndDerivs);
    end
%[text] %[text:anchor:H_4B97FB6A] ### Read input
    numDOFsPerNode = 3; % one vertical displacement and two cross-sectional rotations
    numNodes = height(msh.nodes);
    numDOFs = numNodes*numDOFsPerNode;
    numEl = height(msh.elements);
    numNodesEl = width(msh.elements);
    numDOFsEl = numDOFsPerNode*numNodesEl;
    nodesElPageWise = vertcat(reshape(pagetranspose(reshape(msh.nodes(msh.elements, 1), ...
        [], numNodesEl)), 1, [], numEl), ...
        reshape(pagetranspose(reshape(msh.nodes(msh.elements, 2), [], numNodesEl)), ...
        1, [], numEl));
%[text] %[text:anchor:H_110BB61E] ### Initialization of the page-wise element stiffness matrices and load vectors
    KePageWise = zeros(numDOFsEl, numDOFsEl, numEl);
    FePageWise = zeros(numDOFsEl, 1, numEl);
%[text] %[text:anchor:H_8203790B] ### Construction of the page-wise Element Freedom Tables (EFTs)
    EFT = squeeze(reshape(vertcat(3*reshape(transpose(msh.elements), 1, numNodesEl, ...
        numEl)-2, 3*reshape(transpose(msh.elements), 1, numNodesEl, numEl)-1, ...
        3*reshape(transpose(msh.elements), 1, numNodesEl, numEl)), numDOFsEl, 1, ...
        numEl));
%[text] %[text:anchor:H_B646C116] ### Construction of the page-wise material matrices
    C = [propStr.alpha*propStr.G*propStr.t 0                                 0                    0                     0
         0                                 propStr.alpha*propStr.G*propStr.t 0                    0                     0
         0                                 0                                 propStr.D            propStr.nu*propStr.D  0
         0                                 0                                 propStr.nu*propStr.D propStr.D             0
         0                                 0                                 0                    0                     propStr.D/2*(1 - propStr.nu)];  
    CPageWise = repmat(C, 1, 1, numEl);
%[text] %[text:anchor:H_F67D65B3] ### Gauss points and weights for the numerical integration
    if strcmp(func2str(computeBasisFunctionsAndDerivs), ...
            "computeBilinearBasisFunctionsAndFirstDerivatives")
        numGP = 2;
    elseif strcmp(func2str(computeBasisFunctionsAndDerivs), ...
            "computeBiquadraticBasisFunctionsAndFirstDerivatives")
        numGP = 4;
    end
    [xiGP, GWXi] = getGaussPointsAndWeightsOverUnitDomain(numGP);
    [etaGP, GWEta] = getGaussPointsAndWeightsOverUnitDomain(numGP);
%[text] %[text:anchor:H_5BAE26AB] ### Loop over all the Gauss points for the numerical integration
for jj = 1:height(GWEta)
    for ii = 1:height(GWXi)
%[text] %[text:anchor:H_A5A5CFA0] #### Basis functions at the Gauss point
        [dN, ~] = computeBasisFunctionsAndDerivs(xiGP(ii), etaGP(jj));
        numBF = height(dN);
        if numBF ~= numNodesEl
            error("Numner of nodes does not match the number of basis functions");
        end
        dNPageWise = repmat(dN, 1, 1, numEl);
%[text] %[text:anchor:H_D736DE3A] #### Pagewise basis functions' matrix
%[text] $\\mathbf{N} = \\left\[ \\begin{array}{ccccccc} N\_1(\\xi,\\eta) & 0 & 0 & \\cdots &  N\_n(\\xi,\\eta) & 0 & 0 \\\\ 0 & N\_1(\\xi,\\eta) & 0 & \\cdots &  0 & N\_n(\\xi,\\eta) & 0 \\\\\n0 & 0 & N\_1(\\xi,\\eta) & \\cdots & 0 & 0 & N\_n(\\xi,\\eta) \\end{array} \\right\]$
        NmtxPageWise = zeros(3, numDOFsEl, numEl);
        NmtxPageWise(1, 3*(1:numNodesEl) - 2, :) = dNPageWise(1:numNodesEl, 1, :);
        NmtxPageWise(2, 3*(1:numNodesEl) - 1, :) = dNPageWise(1:numNodesEl, 1, :);
        NmtxPageWise(3, 3*(1:numNodesEl), :) = dNPageWise(1:numNodesEl, 1, :);
%[text] %[text:anchor:H_3BC907BB] #### Page-wise Jacobian matrix
        JacobianMtxPagewise = pagemtimes(dNPageWise(:, 2:3, :), 'transpose', ...
            nodesElPageWise, 'transpose');
%[text] %[text:anchor:H_F3ABC031] #### Page-wise basis functions' derivatives with respect to the physical space
        dNdXPageWise = pagetranspose(pagemldivide(JacobianMtxPagewise, ...
            pagetranspose(dNPageWise(:, 2:3, :))));
%[text] %[text:anchor:H_9EA21574] #### Page-wise B-operator matrix
        BmtxPageWise = zeros(5, numDOFsEl, numEl);
        BmtxPageWise(1, 3*(1:numNodesEl) - 2, :) = dNdXPageWise(1:numNodesEl, 1, :);
        BmtxPageWise(1, 3*(1:numNodesEl), :) = dNPageWise(1:numNodesEl, 1, :);
        BmtxPageWise(2, 3*(1:numNodesEl) - 2, :) = dNdXPageWise(1:numNodesEl, 2, :);
        BmtxPageWise(2, 3*(1:numNodesEl) - 1, :) = -dNPageWise(1:numNodesEl, 1, :);
        BmtxPageWise(3, 3*(1:numNodesEl), :) = dNdXPageWise(1:numNodesEl, 1, :);
        BmtxPageWise(4, 3*(1:numNodesEl) - 1, :) = -dNdXPageWise(1:numNodesEl, 2, :);
        BmtxPageWise(5, 3*(1:numNodesEl) - 1, :) = -dNdXPageWise(1:numNodesEl, 1, :);
        BmtxPageWise(5, 3*(1:numNodesEl), :) = dNdXPageWise(1:numNodesEl, 2, :);
%[text] %[text:anchor:H_3F004070] #### Computation of the element stiffness matrices and element load vectors through page-wise computations
        KePageWise = KePageWise + ...
            pagemtimes(pagemtimes(pagemtimes(BmtxPageWise, 'transpose', CPageWise, 'none'), ...
                BmtxPageWise), pagedet(JacobianMtxPagewise))*GWXi(ii)*GWEta(jj);
        FePageWise = FePageWise + ...
            pagemtimes(pagemtimes(NmtxPageWise, 'transpose', ...
            repmat([propStr.pBar; propStr.mxBar; propStr.myBar], 1, 1, numEl), 'none'), ...
                pagedet(JacobianMtxPagewise))*GWXi(ii)*GWEta(jj);
%[text] 
    end
%[text] 
end
%[text] %[text:anchor:H_FF484344] ### Assembly to the master stiffness matrix and consistent nodal force vector using [`sparse`](https://www.mathworks.com/help/matlab/ref/sparse.html)-matrices
[K, F] = assembleSparseMatrices ...
    (EFT, numDOFs, numDOFsEl, numEl, KePageWise, FePageWise);
%[text] 
end

